// Exhaustive self-checking testbench (generated by LSE)
// Run: iverilog -o sim tb_full_adder.v full_adder.v && vvp sim
`timescale 1ns / 1ps
module tb_full_adder;
    reg  [2:0] x;
    wire [1:0] y;
    integer errors = 0;
    full_adder dut (.a(x[2]), .b(x[1]), .cin(x[0]), .sum(y[0]), .cout(y[1]));

    // compare y with the expected value, ignoring don't-care bits (care = 0)
    task check(input [1:0] expected, input [1:0] care);
        if (((y ^ expected) & care) !== 0) begin
            $display("MISMATCH x=%b y=%b expected=%b", x, y, expected);
            errors = errors + 1;
        end
    endtask

    initial begin
        x = 3'd0; #1 check(2'b00, 2'b11);
        x = 3'd1; #1 check(2'b01, 2'b11);
        x = 3'd2; #1 check(2'b01, 2'b11);
        x = 3'd3; #1 check(2'b10, 2'b11);
        x = 3'd4; #1 check(2'b01, 2'b11);
        x = 3'd5; #1 check(2'b10, 2'b11);
        x = 3'd6; #1 check(2'b10, 2'b11);
        x = 3'd7; #1 check(2'b11, 2'b11);
        if (errors == 0) $display("PASS: all 8 input combinations match");
        else $display("FAIL: %0d mismatches", errors);
        $finish;
    end
endmodule
